h=read(s['holdoutPath']);sel=read(s['combinedSelectionPath']);proof=read(s['finalExportValidationPath']);demo=read(R.parent.parent/'Trading_Manager_State.json')
if proof['holdoutSHA256']!=digest(s['holdoutPath']) or proof['issues']:raise RuntimeError('final_validation_proof_mismatch')
folder=Path(proof['reportFolder']);now=datetime.now(timezone.utc);suffix=now.strftime('%Y%m%dT%H%M%S%fZ')
